CREATE TABLE IF NOT EXISTS posts (id TEXT PRIMARY KEY NOT NULL,title TEXT NOT NULL,excerpt TEXT NOT NULL,content TEXT NOT NULL,contentFormat TEXT NOT NULL DEFAULT 'text',country TEXT NOT NULL,language TEXT NOT NULL,category TEXT NOT NULL,image TEXT NOT NULL DEFAULT '',author TEXT NOT NULL,date TEXT NOT NULL,published INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS posts_country_published ON posts(published,country);
CREATE INDEX IF NOT EXISTS posts_language ON posts(language);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY NOT NULL,email TEXT NOT NULL UNIQUE,name TEXT NOT NULL,passwordHash TEXT,googleSub TEXT UNIQUE,createdAt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (hash TEXT PRIMARY KEY NOT NULL,userId TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_user ON sessions(userId);
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires);
CREATE TABLE IF NOT EXISTS events (key TEXT PRIMARY KEY NOT NULL,visitor TEXT NOT NULL,type TEXT NOT NULL,postId TEXT NOT NULL,date TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS events_visitor ON events(visitor);
CREATE INDEX IF NOT EXISTS events_post ON events(postId);
CREATE INDEX IF NOT EXISTS events_date ON events(date);
CREATE TABLE IF NOT EXISTS uploads (filename TEXT PRIMARY KEY NOT NULL,mime TEXT NOT NULL,size INTEGER NOT NULL,createdAt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits (key TEXT PRIMARY KEY NOT NULL,count INTEGER NOT NULL,resetAt INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS imports (source TEXT PRIMARY KEY NOT NULL,completedAt TEXT NOT NULL);
